INSERT INTO `btime_ajil` (`id`, `ajil`, `tailbar`, `credit`, `at_id`, `user_id`, `tuluv`) VALUES
(1, 'Сургалтын байгууллагын сургалт арга зүй, мэргэжлийн болон сургалт-арга зүйн зөвлөлөөр зөвшөөрөгдсөн, салбарын тэргүүлэх эрдэмтдийн тодорхойлолт, шүүмж авсан ном сурах бичиг бичиж хэвлүүлсэн, хамтран бичсэн', '-Сурган заах арга зүйн зөвлөлийн дүгнэлт\n-Захирлын зөвлөлийн хурлын тэмдэглэл\n-Гарын авлагын хэрэглэж буйг нотлох нотолгоо', 'Үндэсний хэмжээний сурах бичиг бичсэн бол -2 багц цаг, Багт ажилласан бол 1 багц цаг', 3, 42, 1),
(2, 'Мэргэжлийн болон техникийн боловсролын сургалтын төлөвлөгөө боловсруулсан (багт)', '- Хэвлэгдсэн ном, сэтгүүл', '- Шинээр-0.5 багц цаг, - Шинэчилсэн-0.3 багц цаг', 3, 42, 1),
(3, 'Мэргэжлийн стандарт боловсруулах багт ажиллавал', 'Мэргэжлийн стандарт нь хэрэглээнд нэвтэрсэн байх.\n-Багт орж ажилласныг батлах тушаал, шийдвэр\n-Батлагдсан стандарт', '1.0 багц цаг', 3, 42, 1),
(4, 'ЧСС-ын хөтөлбөр, техникийн боловсролын сургалтын хөтөлбөр боловсруулж, баталгаажуулсан бол', 'Хичээлийн иж бүрэн хөтөлбөр', 'Мэргэжлээр (багт) 1 багц цаг, нэгж-0.1 багц цаг', 3, 42, 1),
(5, 'Сургалтын хэрэглэгдэхүүний боловсруулалт (зурагт болон биет үзүүлэн, слайд, аудио ба видео бичлэг)', 'Зурагт болон биет үзүүлэн, слайд, аудио ба видео бичлэг', 'Чадамжийн нэгжээр 0.4 багц цаг', 2, 42, 1),
(6, 'Лаборатори, дадлагын газар, кабинет байгуулсан бол', '- Сургалтын үйл ажиллагааны чиглэлээр судалгаа шинжилгээний ажилд оролцсон тушаал, албан тоот\n-Авсан патентын хуулбар', 'Шинээр 1 багц цаг, Шинэчилбэл 0.3 багц цаг', 4, 42, 1),
(7, 'Хөдөлмөрийн аюулгүй байдал, эрүүл ахуйг хангаж ажилласан бол', 'Хөдөлмөрийн аюулгүй байдал, эрүүл ахуйг хангаж ажилласан тайлан', '0.05 багц цаг', 10, 42, 1),
(8, 'Дадлагын газар, лаборатори, кабинет хариуцсан байдал', '-Лаборатори, дадлагын газрын тохижолт, биет үзүүлэн, багаж тоног төхөөрөмжийн хэрэглээ, бүрэн бүтэн байдлыг хангасан байх\n-Эд хөрөнгийн ашиглалт, хамгаалалт сайтай байх', '0.2 багц цаг', 2, 42, 1),
(9, 'Жижүүр багшийн үүргийг хангалттай сайн гуйцэтгэсэн', 'Жижүүр багшийн үүргийг хангалттай сайн гүйцэтгэсэн тэмдэглэл', '0.05 багц цаг', 2, 42, 1),
(10, 'Сургалтын орчин бүрдүүлсэн байдал /ангийн эд хогшлын бүрэн бүтэн байдал, ангийн тохижилт/  (Сар бүр)', '-Мэргэжлийн онолын болон ерөнхий эрдмийн кабенитын тохижилт, кабенитын булан үзүүлэн, эд хогшлын бүрэн бүтэн байдлыг хангасан байх\n-Цэвэрлэгээний хуваарьтай бөгөөд цэвэрлэгээ, үйлчилгээг тогтмол хийдэг байх.', '0.1 багц цаг', 2, 42, 1),
(11, 'Сургалтын байгууллага, суралцагчийн зөвлөл, хамт олны зохион байгуулсан ажил, тэмцээн уралдаанд анги хамт олноо удирдан оролцож, шагналт байранд шалгарсан байдал', 'Арга хэмжээний удирдамж\n-Шалгарсныг илэрхийлэх өргөмжлөл, медаль, бусад зүйлс\n-Зураг\n- Нэгтгэсэн тайлан', '0.03 багц цаг', 9, 42, 1),
(12, 'Бусад байгууллагаас зохион байгуулсан ажил, тэмцээн уралдаанд багш /бэлтгэсэн суралцагч/ шагналт байранд шалгарсан байдал (СА-аас зөвшөөрөгдсөн)', '-Арга хэмжээний удирдамж\n-Шалгарсныг илэрхийлэх өргөмжлөл, медаль, бусад зүйлс\n-Зураг\n- Нэгтгэсэн тайлан', '0,1 багц цаг', 3, 42, 1),
(13, 'Сургалтын албаны зөвшөөрлөөр дугуйлан секц, сонгон удирдаж, амжилттай зохион байгуулсан байдал', '- Сургалтын албаны зөвшөөрөлтэй байх.\n- Төлөвлөгөө боловсруулж хэрэгжүүлсэн байх. /нийт 72 цагаас багагүй байх/\n- Тайлан, үзэсгэлэн, уралдаан тэмцээн зохион байгуулсан байх.\n- Батлагдсан төлөвлөгөө\n- Сар бүрийн тайлан\n- Суралцагчдын ирц, оролцооны мэдээлэл\n- Үзэсгэлэнгийн зураг', '1,0 багц цаг', 9, 42, 1),
(14, 'Олимпиад, мэргэжлийн уралдаанд багш өөрөө болон суралцагч амжилт гаргасан бол', 'Удирдамж, өргөмжлөл болон бусад нотлох баримт', 'Олон улсад байр эзэлвэл - 2 багц цаг, оролцвол 0.2 багц цаг Улс: 1 байр 1.5 багц цаг\nII байр 1 багц цаг\nIII байр 0.8 багц цаг Бүс (хот, аймаг, дүүрэг):\nI байр 0.8 багц цаг\nII байр 0.6 багц цаг\nIII байр 0.4 багц цаг Улс бүсийн тэмцээнд тусгай байр эзэлвэл 0.2 багц цаг Улс бүсийн тэмцээнд оролцвол -0.1 багц цаг\nСургууль:\nI	байр 0.3 багц цаг\nII	байр 0.2 багц цаг\nIII	байр 0.1 багц цаг', 3, 42, 1),
(15, 'Анги хамт олноо сурлага хүмүүжлийн зөрчилгүй хариуцан ажилласан байдал', 'Ирцийн бүртгэл, суралцагчдын хичээлд оролцох идэвх оролцоо', '0,2 багц цаг', 2, 42, 1),
(16, 'Зөвлөмж, эрдэм шинжилгээний өгүүлэл, илтгэл бичиж нийтлүүлбэл (гадаад, дотоодын сонин сэтгүүл эрдэм шинжилгээний бичигт)', 'Нийтлэл, эмхэтгэл болон бусад нотлох баримт', 'Дотоодод 0.5 багц цаг, гадаадад 0.7 багц цаг', 3, 42, 1),
(17, 'Ном, сурах бичиг редакторласан бол /тухай бүрт/', '-Сургуулийн сурган заах арга зүйн зөвлөлөөр хэлэлцүүлсэн байх\n-Захирлын зөвлөлд танилцуулсан байх\n-Сургалтад хэрэглэж эхэлсэн байх\n-Тухайн хичээлийн жилд шинээр боловсруулсан байх', '0,2 багц цаг', 3, 42, 1),
(18, 'Бие даасан болон хамтарсан гарын авлага бичиж хэвлүүлсэн бол', 'Гарын авлага бусад нотлох баримт', 'Бие даасан- 0.7 багц цаг, хамтарсан -0.3 багц цаг', 3, 42, 1),
(19, 'Сургалтын байгууллага нэр дээр төсөл боловсруулж, хэрэгжүүлсэн бол', 'Төсөл болон бусад нотлох баримт', '1 багц цаг', 4, 42, 1),
(20, 'Эрдэм шинжилгээ, онол, практикийн бага хуралд илтгэл тавьж амжилттай оролцсон бол', 'Нотлох баримт бүрдүүлэх', 'Улс:\nI байр 1 багц цаг\nII	байр 0.8 багц цаг\nIII	байр 0.6 багц цаг Бүс (хот, аймаг, дүүрэг):\nI	байр 0.5 багц цаг\nII	байр 0.4 багц цаг\nIII	байр 0.3 багц цаг Улс бүсийн тэмцээнд тусгай байр эзэлвэл: 0.2 багц цаг\nУлс бүсийн тэмцээнд оролцвол- 0.1 багц цаг\nСургууль:\nI байр 0.3 багц цаг\nII	байр 0.2 багц цаг\nIII	байр 0.1 багц цаг Сургуульд оролцсон бол 0.05 багц цаг', 3, 42, 1),
(21, 'Хөндлөнгийн үнэлгээгээр сурлагын чанарт ахиц гарсан байдал', '-Сургуулийн захиргаа болон хөндлөнгийн байгууллагаас авсан шалгалт байх.\n- Суурь шалгалтын дүнгээс өсч стандарт хангалтыг 75%-иас дээш биелүүлсэн байх.\n-Шалгалтыг багшийн заасан хичээлээр авсан байх.', '0,3 багц цаг', 3, 42, 1),
(22, 'Сургалтын байгууллага, сургалтын үйл ажиллагааны чиглэлээр судалгаа, шинжилгээний ажилд оролцож патент авбал', 'Патент болон бусад нотолгоо', '1 багц цаг', 4, 42, 1),
(23, 'Тухайн жилд докторын зэрэг хамгаалсан бол', 'Нотолгоо', 'Бүтээлийн ЧӨЛӨӨ аваагүй бол 2 багц цаг, бүтээлийн чөлөө авсан бол 0.5 багц цаг', 4, 42, 1),
(24, 'Суралцагч, багш, хамт олны дунд семинар, уралдаан, тэмцээн зохион байгуулж, санаачилгатай ажилласан (СА-аас зөвшөөрсөн) байдал', 'Удирдамж болон бусад нотолгоо', '0.1 багц цаг', 3, 42, 1),
(25, 'Бичиг баримт, мэдээ судалгаа, бүртгэл хөтлөлт', '- Албан тушаалын болон хариуцсан анги, дадлагын газар бусад үйл ажиллагаатай холбоотой мэдээ, судалгааг цаг хугацаанд нь гаргаж өгсөн байх\n- Холбогдох судалгаа, статистик мэдээ', '0,06 багц цаг', 13, 42, 1),
(26, 'Сургуулийн захиргаанаас өгсөн ажил үйлчилгээ, үүрэг даалгаврыг амжилттай сайн (үүрэг даалгаврын хуудсыг үндэслэн) гүйцэтгэсэн байдал', '-Багш нарт тусгайлан өгсөн үүрэг даалгаврыг амжилттай гүйцэтгэсэн байх.', '1 багц цаг', 4, 42, 1),
(27, 'Тэгш хамран сургах, хөгжлийн бэрхшээлтэй суралцагчтай ажилласан бол', 'Хөгжлийн бэрхшээлтэй суралцагчдын хүртээмжийн асуудалд анхаарч ажилласан байх', '0,1 багц цаг', 2, 42, 1),
(28, 'Багш нь суралцагчаа гарааны бизнес эрхлүүлсэн, суралцагчаа хөгжүүлэх замаар шинэ санаа, бүтээл хамтран гаргасан бол', ' -Суралцагчдын хоршооны төлөвлөгөө \n-Суралцагчдын хоршоо ажиллуулсан, үр дүнг тооцсон тайлан, үнэлгээ', '0,3 багц цаг', 3, 42, 1),
(29, 'Багш нь онлайн сургалт зохион байгуулсан', '-Суралцагчдын хэрэгцээ шаардлагад нийцсэн байх       \n-Хичээлийн төлөвлөгөөтэй уялдсан, агуулгыг бүрэн хамарсан байх.\n-Цахим хичээлийн боловсруулалт бүрэн хийгдсэн\n-Сүүлийн үеийн програмаас сонгож ашигласан байх\n-Дуу хоолойн бичлэгтэй байх\n-Бэлэн бичлэг ашигласан бол орчуулга заавал хийх\n-Технологийн карт, тараах материал оруулсан байх\n-Үр дүнг тооцох сорилтой байх\n-Гэрийн даалгавар болон бие даалтын ажлыг заавал оруулсан байх\n-Хичээлтэй холбоотой нэмэлт материал оруулсан байх\n-Компьютер болон гар утаснаас үзэх боломжтой байх', '0.2 багц цаг', 3, 42, 1),
(30, 'Багш нь үндсэн мэргэжлээрээ бие даан мэргэжил боловсролоо дээшлүүлсэн бол (сургалтын байгууллага,төсөл хөтөлбөр, яам түүний харьяа байгууллагын төлөвлөсөн сургалт хамаарахгүй)', '-Сургалтад хамрагдсаныг гэрчлэх бичиг баримт\n-Өөрийн зардлаар суралцсаныг нотлох санхүүгийн баримт\n-Түгээн дэлгэрүүлэлт хийсэн байх, тайлан хавсаргах', 'Баримтыг үндэслэн 0.4 багц цаг', 14, 42, 1),
(31, 'Багш нь төгсөгчдийг ажлын байраар хангасан бол(нотлох баримтаар)', ' -Тухайн байгууллагын ажилд авсан тушаал, албан бичиг', 'Нэг ажлын байр нь 0.01 багц цаг', 3, 42, 1),
(32, 'Ажил үйлчилгээ гүйцэтгэх замаар сургуульд оруулсан ашгийн 600 мянган төгрөг тутамд', '-Орлогыг нотлох санхүүгийн баримт\n-Үйл ажиллагааны тайлан', '1,0 багц цаг', 12, 42, 1),
(33, 'Багш суралцагчийн хяналтын графикийг (давтлага, зөвлөгөө өгөх, бие даалт тооцож, явцын шалгалт авах) тогтмол мөрдөж ажилласан байдал', '-Баталгаажсан хяналтын график\n-Суралцагчдын оролцооны мэдээлэл, ирцийн бүртгэл\n-Үнэлгээний хуудас ', '0,1 багц цаг', 2, 42, 1),
(34, 'Баг ахалж амжилттай ажилласан (cap, жилийн ажлын төлөвлөгөө, ажлын үр дүнг харгалзан) бол', ' -Багийн ажлын төлөвлөгөөг батлуулсан байх \n- Багийн хурал цуглааныг зохион байгуулан дотоод зохион байгуулалттай холбогдох ажлыг гүйцэтгэсэн байх. /төлөвлөгөө, тайлан, мэдээ/\n- Бүтээлч ажил зохион байгуулсан байх.\n- Сургуулийн үндсэн үйл ажиллагааг дэмжсэн, шинэ санал санаачилгыг хэрэгжүүлсэн байх.\n- Захирлын тушаалаар батлагдсан ажлын хэсэгт орж ажилласан, тайлан мэдээг гаргасан байх', '0,1 багц цаг', 4, 42, 1),
(35, 'Бүрэн дунд боловсролын төгсөлтийн шалгалтад бэлтгэх давтлага өгсөн', '-Батлагдсан хуваарь\n-Суралцагчдын бүртгэл\n -Сургалтын албаны ажилтны  ирц бүртгэл   \n-Нэгдсэн тайлан  ', '1 ангид-0.1 багц цаг', 2, 42, 1),
(36, 'Курсийн болон график тооцооны ажил удирдсан бол', '-Баталгаажсан үнэлгээний хуудас', '1 суралцагчид 0,03 багц цаг', 2, 42, 1),
(37, 'Дипломын төсөл удирдсан бол', '-Баталгаажсан үнэлгээний хуудас', '1 сурагчид -0.15 багц цаг', 2, 42, 1);
