INSERT INTO `sanal` (`id`, `title`, `body`, `userid`) VALUES
(11, 'Стратеги төлөвлөгөө санал', 'Зөв хандлага бүхий гэж оруулах', 0),
(9, 'Стратеги төлөвлөгөө санал', 'Хандлага -үнэт зүйл дээр оруулья', 0),
(10, 'Стратеги төлөвлөгөө санал', 'эрхэм зорилго дээр- зөв хандлага бүхий гэж оруулах', 0),
(12, 'Стратеги төлөвлөгөө санал', 'Дараах 3 саналыг дэмжиж байна.', 0),
(13, 'Стратеги төлөвлөгөө санал', 'Зөв хандлага бүхий гэж оруулах', 0),
(14, 'Стратеги төлөвлөгөө санал', 'Санал нэг байна', 0),
(15, 'Стратеги төлөвлөгөө санал', 'Саналыг дэмжиж байна', 0),
(16, 'Стратеги төлөвлөгөө санал', 'Чадамжийн төв дор хаяж 2 мэргэжил дээр байгуулах', 0),
(17, 'Стратеги төлөвлөгөө санал', 'Саналыг дэмжиж байна', 0),
(18, 'Стратеги төлөвлөгөө санал', 'Саналыг дэмжиж байна.', 0),
(19, 'Стратеги төлөвлөгөө санал', 'Үндэсний ч юм уу монгол эх оронч гэсэг үг оруулах хэрэгтэй ', 0),
(20, 'Стратеги төлөвлөгөө санал', 'Эко сургууль хөтөлбөрийн хүрээнд ногоон хөгжлийг дэмжсэн арга хэмээ үйл ажилгааг зохион байгуулах', 0),
(21, 'Стратеги төлөвлөгөө санал', 'Журналыг цахимжуулах, сургалтын тоног төхөөрөмж, хэрэгсэлийг мэргэжлийн байгууллагаар баталгаажуулах арга хэмжээг тусгах, цахим сангийн үйл ажиллагааг эрчимжүүлэх, төгсөгчдийн хөдөлмөр эрхлэлтийг дэмжихэд ажил олгогч ААНБ-ийн оролцоог нэмэгдүүлэхэд тэднийг урамшуулах системийг тусгах, зах зээлийн судалгааг мэргэжлийн байгууллагатай хамтран эмхтгэл гарган суурь судалгааг бий болгох, сургалтын нэгдсэн програм бий болгох', 0),
(22, 'Стратеги төлөвлөгөө санал', 'Суралцагчдын шатлан суралцах боломжийг бүрдүүлэх, багшийн боловсролын зэргийг ахиулах, эрэлттэй тэргүүлэх чиглэлийн мэргэжлийн хөтөлбөрүүдийг магадлан итгэмжлэлд хамруулах, дотуур байрны амьдрах орчинг сайжруулах арга хэмжээг тусгах', 0),
(23, 'Стратеги төлөвлөгөө санал', 'Багш нарын эрдэм шинжилгээ судалгааны ажлыг дэмжин бүтээлийн эмхэтгэл гаргахад дэмжлэг үзүүлэх', 0),
(24, 'Стратеги төлөвлөгөө санал', 'Суралцагчдын 2+1 олон улсын хөтөлбөр хэрэгжүүлэх,', 0);
INSERT INTO `strategy_ajil` (`id`, `zorilt_id`, `body`, `huvi`, `tailbar`) VALUES
(3, 1, 'Улсын болон аймаг орон нутгийн хөгжлийн бодлого төлөвлөлттэй уялдуулан сургуулийн бодлого, хөтөлбөр дүрэм, журмыг шинэчлэх', 60, '2022 онд 8 дүрэм, журам, 2023 онд 1 журмыг шинэчлэн боловсруулж, дүрэм журмын эмхэтгэлийг шинэчилсэн. '),
(4, 1, 'Сургуулийн эрх ашгийг хамгаалах, нийгэм дэх нэр хүндийг өсгөх', 65, 'Дэд хөтөлбөр боловсруулагдаагүй. Нээлттэй хаалганы өдөрлөг зохион байгуулсан'),
(5, 1, 'Цахим мэдээлэлд тулгуурласан төлөвлөлт, менежментийг хөгжүүлэн, цахим санг бүрдүүлэх', 90, 'Сүүлийн 10-н жилийн 2382 бичгийг цахимжуулсан. '),
(6, 1, 'Сургуулийн дэвшүүлсэн зорилт, түүний хэрэгжилт, хүрсэн үр дүнг шалгуур үзүүлэлтээр үнэлж дүгнэх, ажлын чанар, гүйцэтгэлд хяналт шалгалт хийх', 91, '53 удаагийн дотоод хяналт шинжилгээ, үнэлгээг зохион байгуулсан. '),
(7, 1, 'Хөндлөнгийн байгууллагаар чанарын баталгаажилт хийлгэх', 100, '“Хэвлэлийн график дизайнч”, “Барилгын засал чимэглэлчин” мэргэжлийн 2 хөтөлбөрийг магадлан итгэмжлүүлсэн. '),
(8, 1, 'Сургуулийн багш ажилтнууд, суралцагчдын аюулгүй байдал, эрүүл ахуйг хангах, аюулгүй сургалтын орчин, ажлын байрыг бий болгох', 90, 'Суралцагчдад чиглэсэн арга хэмжээ зохион байгуулсан, галын хор шинэчилсэн. '),
(9, 2, 'Техникийн болон мэргэжлийн боловсролын шаталсан, залгамж холбоог хангасан сургалтын хөтөлбөрийг боловсруулан хөгжүүлэх', 90, '10 хөтөлбөрийн сайжруулалт хийсэн. '),
(10, 2, 'Цахим, зайн сургалтын дэвшилтэт арга зүйг сургалтад нэвтрүүлэх, хөгжүүлэх', 85, 'Цахим хичээлийн санд хичээлүүдийг байршуулсан. '),
(11, 2, 'Шаталсан хөтөлбөрийн суралцахуйн үр дүн, агуулгад харьцуулалт хийх замаар хөтөлбөрт дүн шинжилгээ хийх', 85, 'Чанарын үнэлгээнд хамрагдсан. '),
(12, 2, 'Шаталсан сургалтын хөтөлбөрөөр дэвшин суралцах үйлчилгээг чанартай зохион байгуулах', 75, 'Шатлан суралцагчдын тоог 12 хувиар нэмэгдүүлсэн. Шатлан суралцах журам боловсруулан, мөрдөж ажилласан. '),
(13, 2, 'Хөтөлбөрийн дотоод чанарын баталгаажуулалтыг тогтмол хийх', 100, 'Багш бүрээр хөтөлбөрт дотоод хяналт шинжилгээ, үнэлгээг хийж, зөвлөмж хүргүүлэн ажилласан.'),
(14, 2, 'Хөдөлмөрийн зах зээлийн эрэлт, нийлүүлэлтийн судалгааг хийх', 60, 'Мөшгих судалгаа хийдэг.'),
(15, 2, 'Тэргүүлэх чиглэлээр техникийн болон мэргэжлийн боловсролын шинэ хөтөлбөр нээх', 55, '5 мэргэжлээр шинээр мэргэжил нээхээр Удирдах зөвлөлд санал хүргүүлсэн.'),
(16, 2, 'Сургуулийн элсэлтийн чанарыг сайжруулах, бодлого боловсруулан хэрэгжүүлэх', 50, 'Журам боловсруулан хэрэгжүүлсэн. Хөтөлбөр боловсруулагдаагүй.'),
(17, 2, 'Бүс нутгийн онцлог, бүтээн байгуулалт, үйлдвэрлэлийн өсөлт, аж ахуйн нэгж байгууллагын захиалга болон хөдөлмөрийн зах зээлийн эрэлтэд нийцүүлэн  элсэлт, төгсөлтийн үйл ажиллагааг төлөвлөн зохион байгуулах', 70, '7 мэргэжлээр мэргэжлийн сургалтыг зохион байгуулсан. '),
(18, 2, 'Ажил мэргэжлийн чиг баримжаа олгох  сургалтын модуль хөтөлбөрийг боловсруулан хэрэгжүүлэх', 95, '488 суралцагчид 16 цагийн энтрэпренершип боловсрол олгох сургалт зохион байгуулсан.'),
(19, 2, 'Сургууль-ажил олгогч-төгсөгч хамтын ажиллагааг бэхжүүлэх, эргэх холбоог сайжруулах', 85, 'Хөдөлмөр эрхлэлт 81 хувьтай. Төгсөгчдийн пэйж хуудсыг идэвхжүүлсэн.'),
(20, 3, 'Эцэг эх, асран хамгаалагчидтай хамтын ажиллагааг эрчимжүүлэн, суралцагчдын хүмүүжил төлөвшил, сурах үйл ажиллагааг дэмжих', 68, '3 удаагийн арга хэмжээ зохион байгуулсан. '),
(21, 3, 'Багш суралцагчдын сэтгэл ханамжийн түвшинг тодорхойлох', 65, 'Хүүхдэд ээлтэй байгууллага сэтгэл ханамжийн судалгааг багш, суралцагчдаас авч байгаа. '),
(22, 3, 'Суралцагч хөгжил төвөөр дамжуулан хүүхдэд ээлтэй үйлчилгээг тэгш хүртээмжтэй хүргэх', 60, '6 удаагийн арга хэмжээг зохион байгуулсан. '),
(23, 3, 'Багш суралцагчийн сурч хөгжих үйл явцыг дэмжих,  уншигчдын эрэлт хэрэгцээг хангахуйц үйлчилгээг үзүүлэх', 95, 'Номын тоог нэмэгдүүж, орчинг сайжруулсан. '),
(24, 3, 'Суралцагчдыг болзошгүй эрсдэлээс урьдчилан сэргийлэх, хамгаалах', 95, 'Сургалт, арга хэмжээг зохион байгуулсан. 4 удаагийн арга хэмжээнд 758 суралцагч хамрагдсан. '),
(25, 3, 'Эрүүл мэндийн боловсролыг нэмэгдүүлэх, эрүүл аж төрөх, амьдралын зөв хэв маягт суралцуулах, зөвлөгөө тусламж үйлчилгээ үзүүлэх', 91, 'Эрүүл мэндийн мэдлэгийг нэмэгдүүлэх сургалтыг өрхийн эрүүл мэндийн төвтэй хамтран зохион байгуулж, урьдчилан сэргийлэх үзлэгт тогтмол хамруулдаг. 5 удаагийн арга хэмжээ зохион байгуулж 542 суралцагч хамрагдсан. '),
(26, 3, '“Бид нэг байрныхан” уриатайгаар  дотуур байрны суралцагчдыг тэгш хөгжих боломжийг бүрдүүлэх', 90, '14 удаагийн арга хэмжээг зохион байгуулсан.'),
(27, 4, 'Орон нутгийн болон үндэсний хэмжээний томоохон аж ахуйн нэгж байгууллагуудтай хамтын ажиллагаагаа өргөжүүлэх', 100, 'Түншлэгчдийн тоог 30 хувиар нэмэгдүүлсэн. '),
(28, 4, 'Мэргэжлийн зөвлөл байгуулан үйл ажиллагааг тогтмолжуулан хамтын ажиллагааг өргөжүүлэх', 45, '3 мэргэжлийн зөвлөл байгуулсан. '),
(29, 4, 'Чадамжид суурилсан сургалтын хөтөлбөрийг хамтран хэрэгжүүлэх', 95, '9 мэргэжлийн хөтөлбөрт ажил олгогчдыг оролцуулан саналыг тусгаж, 58 ажил олгогч төгсөлтийн шалгалтад оролцсон.  '),
(30, 4, 'Үйлдвэрлэлийн дадлагыг зохион байгуулан, багш, суралцагчдын инноваци, бүтээлч сэтгэлгээг дэмжиж ажиллах', 40, '1 инноваци шингэсэн бүтээл гаргасан. '),
(31, 4, ' Мэргэжлийн багшийг үйлдвэрлэлийн шинэ техник, технологитой танилцуулах, аж ахуйн нэгж байгууллагын инженер техникийн ажилтнуудыг урьж туршлага судлах', 100, '43 багш, ажилтан туршлага судалсан. '),
(32, 4, 'Гадны ижил төстэй үйл ажиллагаа явуулдаг байгууллагад багш ажилтан, суралцагчдыг мэргэжлийн дагуу дадлагажуулах', 85, '8 суралцагч дадлагажиж байгаа'),
(33, 4, 'Төсөл хөтөлбөр хэрэгжүүлдэг олон улсын байгууллагуудтай харилцаа тогтоож, дэмжлэг хүсэх', 90, '8 байгууллагатай санамж бичиг байгуулсан. '),
(34, 5, 'Багш, ажилтнуудыг мэргэшүүлэх болон ахисан түвшний сургалтуудад үе шаттайгаар хамруулах', 85, '39 удаагийн сургалт зохион байгуулсан. '),
(35, 5, 'Багш, ажилтнуудын нийгмийн баталгааг ханган ажиллах', 100, 'Эрүүл мэндийн үзлэг шинжилгээ, гэнэтийн ослын даатгалд хамруулж, үр дүн, ур чадварын нэмэгдэл, тэтгэмжийг олгон ажилласан. '),
(36, 5, 'Багш нарын эрдмийн болон мэргэжлийн зэрэг цол ахиулах тоог нэмэгдүүлэх', 100, 'Мэргэжлийн зэргээ ахиулахад дэмжлэг үзүүлдэг.   '),
(37, 5, 'Багш, ажилтнуудын гүйцэтгэлийн үнэлгээнд суурилсан цалин хөлс, шагнал урамшууллын системийг бий болгох', 100, 'Ажлын гүйцэтгэлийг үнэлэн урамшуулал олгодог. '),
(38, 5, 'Багш хөгжлийн төвийг инновацийн төв болгон өргөжүүлэн ажлын байран дээр тасралтгүй хөгжих орчин нөхцөлийг бүрдүүлэх', 30, 'Холбогдох дээд шатны байгууллагад төсөл хүргүүлсэн.'),
(39, 5, 'Сургалтын орчин нөхцөлийг засварлан сайжруулах', 100, 'Бүрэн хэрэгжсэн.'),
(40, 5, 'Санхүүгийн бодлого төлөвлөлт, ил тод байдлыг тасралтгүй хөгжүүлэх', 90, 'Шилэн дансны мэдээллийг хугацаа хоцорсон 18, мэдээлээгүй 13 мэдээ байна. ');
